sql_query:
SELECT "Year"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Pembrolizumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Year" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Melanoma' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Pembrolizumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_era_bucket(source_value) AS "era"
FROM base;
